# ===================== UTILITIES =====================
class Vector2:
    def __init__(self, x: float, y: float):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2(self.x / scalar, self.y / scalar)

    def magnitude(self) -> float:
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        return Vector2(self.x / mag, self.y / mag) if mag > 0 else Vector2(0, 0)

    def distance_to(self, other) -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)


def lerp(start, end, t):
    return start + (end - start) * t


def clamp(value, min_val, max_val):
    return max(min_val, min(value, max_val))


# ===================== GAME ENTITIES =====================
class Particle:
    def __init__(self, pos: Vector2, color: Tuple[int, int, int], size: float, life: float, velocity: Optional[Vector2] = None):
        self.pos = pos
        self.color = color
        self.size = size
        self.life = life
        self.max_life = life
        self.velocity = velocity if velocity else Vector2(random.uniform(-1, 1), random.uniform(-1, 1))
        self.decay = random.uniform(0.02, 0.05)

    def update(self, dt: float):
        self.pos += self.velocity * dt * 60
        self.life -= self.decay * dt * 60
        self.size *= 0.98

    def is_dead(self) -> bool:
        return self.life <= 0

    def draw(self, screen):
        alpha = self.life / self.max_life
        color_with_alpha = (*self.color, int(255 * alpha))
        surf = pygame.Surface((self.size * 2, self.size * 2), pygame.SRCALPHA)
        pygame.draw.circle(surf, color_with_alpha, (self.size, self.size), self.size)
        screen.blit(surf, (self.pos.x - self.size, self.pos.y - self.size))


class Projectile:
    def __init__(self, pos: Vector2, direction: Vector2, owner: 'Robot', weapon_name: str):
        self.pos = pos
        self.direction = direction.normalize()
        self.owner = owner
        self.weapon_name = weapon_name
        self.speed = 12
        self.damage = WEAPONS[weapon_name]["damage"]
        self.range = WEAPONS[weapon_name]["range"]
        self.traveled = 0
        self.active = True
        self.color = WEAPONS[weapon_name]["color"]
        self.size = 4

    def update(self, dt: float):
        move_vec = self.direction * self.speed * dt * 60
        self.pos += move_vec
        self.traveled += move_vec.magnitude()
        if self.traveled >= self.range:
            self.active = False

    def draw(self, screen):
        pygame.draw.circle(screen, self.color, (int(self.pos.x), int(self.pos.y)), self.size)


class PowerUp:
    def __init__(self, pos: Vector2, type_name: str):
        self.pos = pos
        self.type_name = type_name
        self.info = POWERUPS[type_name]
        self.active = True
        self.pulse = 0

    def update(self, dt: float):
        self.pulse += dt * 3

    def draw(self, screen):
        radius = 12 + math.sin(self.pulse) * 2
        pygame.draw.circle(screen, self.info["color"], (int(self.pos.x), int(self.pos.y)), radius)
        # Draw icon
        font = pygame.font.SysFont(None, 16)
        text = font.render(self.type_name[0].upper(), True, (0,0,0))
        screen.blit(text, (self.pos.x - 4, self.pos.y - 6))


class Objective:
    def __init__(self, name: str, pos: Vector2, team: str, objective_type: str):
        self.name = name
        self.pos = pos
        self.team = team
        self.objective_type = objective_type
        self.captured_by = None
        self.capture_progress = 0.0
        self.points = 0
        self.last_capture_time = 0

    def update(self, dt: float, robots: List['Robot']):
        # Capture logic
        nearby_robots = [r for r in robots if r.pos.distance_to(self.pos) < 60]
        if not nearby_robots:
            return
